[HttpGet("stream")
public async IAsyncEnumerable<string> StreamCompletionAsync(
    [FromQuery] string prompt,
    [FromHeader] string? requestId = null,
    CancellationToken cancellationToken = default)
{
    await foreach (var chunk in _aiService.StreamCompleteAsync(prompt, cancellationToken))
    {
        cancellationToken.ThrowIfCancellationRequested();
        yield return chunk;
    }
}

// Background ingestion worker
public class DocumentIngestionWorker : BackgroundService
{
    private readonly IQueue<DocumentIngestionTask> _queue;
    private readonly IEmbeddingService _embeddingService;
    private readonly IVectorStore _vectorStore;
    private readonly ILogger<DocumentIngestionWorker> _logger;

    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        await foreach (var task in _queue.DequeueAsync(stoppingToken))
        {
            try
            {
                await ProcessDocumentAsync(task, stoppingToken);
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Failed to process document {DocumentId}", task.DocumentId);
                await _queue.RequeueAsync(task, delay: TimeSpan.FromMinutes(5), stoppingToken);
            }
        }
    }

    private async Task ProcessDocumentAsync(DocumentIngestionTask task, CancellationToken ct)
    {
        // Mark as processing
        await _vectorStore.UpdateStatusAsync(task.DocumentId, ProcessingStatus.Processing, ct);

        // Chunk document
        var chunks = await _chunker.ChunkAsync(task.Document, ct);

        // Generate embeddings (batched)
        var embeddings = await _embeddingService.GenerateBatchAsync(chunks, ct);

        // Store in vector database (idempotent)
        await _vectorStore.UpsertAsync(task.DocumentId, chunks, embeddings, ct);

        // Mark as complete
        await _vectorStore.UpdateStatusAsync(task.DocumentId, ProcessingStatus.Completed, ct);
    }
}
